   It keeps research, marginalia, and persona requests in the manuscript. */
.selection-actions {
  position: fixed;
  z-index: var(--z-dropdown);
  width: max-content;
  max-width: min(32rem, calc(100vw - 1rem));
  border: 1px solid color-mix(in srgb, var(--color-ink-muted) 52%, transparent);
  background: color-mix(in srgb, var(--color-paper) 91%, transparent);
  box-shadow: 0 0.65rem 1.8rem rgba(32, 25, 16, 0.2);
  backdrop-filter: blur(14px) saturate(0.9);
  color: var(--color-ink);
}
.selection-actions--above {
  transform: translate(-50%, -100%);
}
.selection-actions--below {
  transform: translateX(-50%);
}
.selection-actions__row {
  display: flex;
  align-items: stretch;
}
.selection-actions__row > button {
  padding: 0.5rem 0.58rem;
